+
+
+/**
+ * 32-bit cyclic redundancy check, or CRC-32 - checksum
+ */
+class Crc32 {
+    crc: number;
+    table: any;
+    constructor() {
+        this.crc = -1;
+        this.table = (() => {
+            let i
+            let j
+            let t;
+            const table = [];
+
+            for (i = 0; i < 256; i++) {
+                t = i;
+                for (j = 0; j < 8; j++) {
+                    t = (t & 1)
+                        ? (t >>> 1) ^ 0xEDB88320
+                        : t >>> 1;
+                }
+                table[i] = t;
+            }
+            return table
+        })()
+    }
+
+    append(data: TypedArray) {
+        let crc = this.crc | 0;
+        const table = this.table;
+        for (let offset = 0, len = data.length | 0; offset < len; offset++) {
+            crc = (crc >>> 8) ^ table[(crc ^ data[offset]) & 0xFF];
+        }
+        this.crc = crc;
+    }
+
+    get() {
+        return ~this.crc;
+    }
+}
+
+
